def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "navigate_to_corridor": And([
            self.corridor_wet,
            Not(self.barrier_placed),
            self.robot_has_package
        ]),
        "navigate_to_reception": And([
            self.corridor_wet,
            Not(self.barrier_placed),
            self.robot_has_package
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
